// Reads db/migrations/*.sql and writes lib/schemaExpectations.ts — the list
// of tables and columns the code expects to exist.
//
// Why a generated file rather than reading the migrations at runtime: the
// admin page runs on Vercel, where the .sql files are not part of the
// serverless bundle. A committed snapshot is always there, and a test keeps
// it honest — add a migration without regenerating and the suite fails.
//
// Usage: npm run schema:snapshot

import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const dir = path.join(root, 'db', 'migrations');

export function readExpectations(migrationsDir = dir) {
  const files = readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort();
  // Replayed in order, adds AND drops: a column added in 006 and dropped in
  // 008 is not something the code expects, and reporting it would train
  // everyone to ignore the audit.
  const tables = new Set();
  const columns = new Set();
  const dropTableColumns = (t) => {
    for (const c of [...columns]) if (c.startsWith(`${t}.`)) columns.delete(c);
  };

  for (const file of files) {
    const sql = readFileSync(path.join(migrationsDir, file), 'utf8')
      // Comments routinely discuss dropped columns in prose; only real
      // statements should move the model.
      .replace(/--[^\n]*/g, '');

    for (const m of sql.matchAll(/create table (?:if not exists )?([a-z_]+)/g)) tables.add(m[1]);
    for (const m of sql.matchAll(/drop table (?:if exists )?([a-z_]+)/g)) {
      tables.delete(m[1]);
      dropTableColumns(m[1]);
    }

    for (const m of sql.matchAll(/alter table (?:if exists )?([a-z_]+)([\s\S]*?);/g)) {
      const table = m[1];
      const body = m[2];
      const renameTable = body.match(/rename to ([a-z_]+)/);
      if (renameTable) {
        tables.delete(table);
        tables.add(renameTable[1]);
        for (const c of [...columns]) {
          if (c.startsWith(`${table}.`)) {
            columns.delete(c);
            columns.add(`${renameTable[1]}.${c.slice(table.length + 1)}`);
          }
        }
        continue;
      }
      for (const c of body.matchAll(/add column (?:if not exists )?([a-z_]+)/g)) {
        columns.add(`${table}.${c[1]}`);
      }
      for (const c of body.matchAll(/drop column (?:if exists )?([a-z_]+)/g)) {
        columns.delete(`${table}.${c[1]}`);
      }
      for (const c of body.matchAll(/rename column ([a-z_]+) to ([a-z_]+)/g)) {
        columns.delete(`${table}.${c[1]}`);
        columns.add(`${table}.${c[2]}`);
      }
    }
  }

  return {
    files,
    tables: [...tables].sort(),
    columns: [...columns].sort(),
  };
}

export function renderSnapshot(exp) {
  const list = (xs) => xs.map((x) => `  '${x}',`).join('\n');
  return `// GENERATED by scripts/schema-snapshot.mjs — do not edit by hand.
// Run \`npm run schema:snapshot\` after adding a migration.

export const MIGRATION_FILES: string[] = [
${list(exp.files)}
];

export const EXPECTED_TABLES: string[] = [
${list(exp.tables)}
];

// "table.column" for columns added by a later migration.
export const EXPECTED_COLUMNS: string[] = [
${list(exp.columns)}
];
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const exp = readExpectations();
  writeFileSync(path.join(root, 'lib', 'schemaExpectations.ts'), renderSnapshot(exp));
  console.log(
    `Wrote lib/schemaExpectations.ts — ${exp.files.length} migrations, ` +
    `${exp.tables.length} tables, ${exp.columns.length} added columns.`
  );
}
